local MazeUI_MainDialog = Class('MazeUI_MainDialog')

-- ========================================================

local KTool = CS.Engine.Lib.KTool
local TextMeshProUGUI = CS.TMPro.TextMeshProUGUI


function MazeUI_MainDialog:__init()
    --print("   ~~~~~~~ MazeUI_MainDialog:__init() ~~~~~~~")
    self.controller = nil
end


function MazeUI_MainDialog:__delete()
    --print("   ~~~~~~~ MazeUI_MainDialog:__delete() ~~~~~~~")
end



function MazeUI_MainDialog:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    --print("   ~~~~~~~ MazeUI_MainDialog:Awake() ~~~~~~~")
    assert( self.BtnBack and self.BtnDismantle and self.BtnReset and self.BtnChoose )
    assert( self.BtnUp and self.BtnDown and self.BtnRight and self.BtnLeft )
    assert( self.BtnUp2 and self.BtnDown2 and self.BtnRight2 and self.BtnLeft2 )
    assert( self.BtnRotate1 and self.BtnRotate2 )
    assert( self.InfoList and self.redThreeTargetInfoOrNode and self.redThreeBtnTarget and self.redThreeBtnPutAway and self.redThreeTxtNumber ) -- 红色三条目 相关的
    assert( self.TipsPopup_BtntPlayState )

    assert( self.fullAreaBtn )
end


function MazeUI_MainDialog:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    --print("   ~~~~~~~ MazeUI_MainDialog:OnDestroy() ~~~~~~~")
end


return MazeUI_MainDialog
